frappe.listview_settings["Quotation"].get_indicator = function(doc) {
    var s = doc.custom_acquisitie_status;
    if (s === "Lead") return ["Lead", "blue"];
    if (s === "Offerte") return ["Offerte", "orange"];
    if (s === "Grote kans bijna binnen") return ["Grote kans", "yellow"];
    if (s === "Opdracht") return ["Opdracht", "green"];
    if (s === "Verloren") return ["Verloren", "red"];
    return [doc.status, "gray"];
};

frappe.ui.form.on("Zapp Bouw7 Koppeling", {
  refresh(frm) {
    if (frm.is_new()) return;
    const invoke = async (action) => {
      if (frm.is_dirty()) await frm.save();
      const response = await frappe.call({
        method: "zapp_bouw7_sync", type: "POST",
        args: {action, mutation_token: frappe.csrf_token},
        freeze: true, freeze_message: "Bouw7-koppeling bijwerken…",
      });
      await frm.reload_doc();
      const result = response.message || {};
      if (action === "test" && !result.connected) {
        frappe.msgprint({title: "Bouw7-verbinding", message: result.error || "Verbinding mislukt.", indicator: "red"});
        return;
      }
      frappe.show_alert({message: result.connected ? `Verbonden met ${result.organization}` : result.status === "running" ? "Er loopt al een synchronisatie." : "Synchronisatie gestart. De voortgang wordt automatisch vernieuwd.", indicator: "green"});
    };
    frm.add_custom_button("Nu bijwerken", () => invoke("start")).addClass("btn-primary");
    frm.add_custom_button("Verbinding testen", () => invoke("test"), "Bouw7");
    frm.add_custom_button("Eerst vergelijken", () => invoke("preview"), "Bouw7");
    frm.add_custom_button("Volledig controleren en bijwerken", () => invoke("full"), "Bouw7");
    frm.add_custom_button("Verwerkingslog", () => frappe.set_route("List", "Zapp Bouw7 Log"), "Bouw7");
    frm.add_custom_button("Openstaande controles", () => frappe.set_route("List", "Zapp Bouw7 Controle", {resolved: 0}), "Bouw7");
    const state = JSON.parse(frm.doc.state_json || "{}");
    const labels = {contacts:"Contacten", employees:"Medewerkers", projects:"Projecten", purchase_invoices:"Inkoopfacturen", sales_invoices:"Verkoopfacturen"};
    const stats = state.stats || {};
    const esc = frappe.utils.escape_html;
    const rows = Object.entries(stats).map(([kind, s]) => `<tr><td>${esc(labels[kind] || kind)}</td><td>${s.created || 0}</td><td>${s.updated || 0}</td><td>${s.unchanged || 0}</td><td>${(s.failed || 0) + (s.conflict || 0)}</td></tr>`).join("");
    const kind = ["Bezig", "Fout"].includes(frm.doc.sync_status) ? ["contacts", "employees", "projects", "purchase_invoices", "sales_invoices"][state.index] : null;
    const position = kind ? `<p>${esc(labels[kind])}: ${Number(state.offset || 0).toLocaleString("nl-NL")} behandeld${state.expected_counts?.[kind] != null ? ` · ${Number(state.expected_counts[kind]).toLocaleString("nl-NL")} in bronselectie` : ""}</p>` : "";
    const heartbeat = frm.doc.last_heartbeat ? `<p class="text-muted">Laatste activiteit: ${esc(frappe.datetime.str_to_user(frm.doc.last_heartbeat))}</p>` : "";
    const error = frm.doc.last_error ? `<div class="alert ${frm.doc.sync_status === "Fout" ? "alert-danger" : "alert-warning"}">${esc(frm.doc.last_error)}${frm.doc.sync_status === "Fout" ? "<br>‘Nu bijwerken’ hervat vanaf het opgeslagen punt. De uurtaak probeert dit ook opnieuw." : ""}</div>` : "";
    frm.fields_dict.progress_html.$wrapper.html(`<p><strong>${esc(frm.doc.sync_status || "Nog niet gestart")}</strong> ${state.dry_run ? "· Vergelijking zonder wijzigingen" : ""}${state.repair_ids ? " · Gerichte herstelronde" : ""}</p>${position}${heartbeat}${error}<table class="table table-bordered"><thead><tr><th>Onderdeel</th><th>Nieuw</th><th>Bijgewerkt</th><th>Ongewijzigd</th><th>Controleren</th></tr></thead><tbody>${rows}</tbody></table>`);
    if (frm.doc.sync_status === "Bezig" && !frm.bouw7_timer) {
      frm.bouw7_timer = setTimeout(() => {
        frm.bouw7_timer = null;
        if (cur_frm === frm && !frm.is_dirty()) frm.reload_doc();
      }, 5000);
    }
  },
});

frappe.ui.form.on('Zapp Calculatie', {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Openen in Open Calc Studio'), () => window.open('/zapp-calculaties?calc=' + encodeURIComponent(frm.doc.name), '_blank'));
        }
    },
    open_editor(frm) {
        if (frm.is_new()) { frappe.msgprint(__('Sla de calculatie eerst op.')); return; }
        window.open('/zapp-calculaties?calc=' + encodeURIComponent(frm.doc.name), '_blank');
    }
});
frappe.listview_settings['Zapp Calculatie'] = Object.assign(frappe.listview_settings['Zapp Calculatie'] || {}, {
    onload(list) {
        list.page.add_inner_button(__('Open Calc Studio'), () => window.open('/zapp-calculaties', '_blank'));
    }
});

const DTT_INTERVAL = {
    'Dagelijks': [1, 'd'], 'Wekelijks': [7, 'd'], 'Tweewekelijks': [14, 'd'],
    'Maandelijks': [1, 'm'], 'Per kwartaal': [3, 'm'], 'Jaarlijks': [12, 'm']
};

function dtt_add(date, freq) {
    const [n, unit] = DTT_INTERVAL[freq];
    return unit === 'd' ? frappe.datetime.add_days(date, n) : frappe.datetime.add_months(date, n);
}

frappe.ui.form.on('Zapp Terugkerende Taak', {
    refresh(frm) {
        if (frm.is_new() || !DTT_INTERVAL[frm.doc.frequentie]) return;
        frm.add_custom_button(__('Markeer als uitgevoerd'), () => {
            const today = frappe.datetime.get_today();
            // Ritme vasthouden: reken vanaf de geplande datum, niet vanaf vandaag
            let next = dtt_add(frm.doc.volgende_keer || today, frm.doc.frequentie);
            while (frappe.datetime.get_diff(next, today) <= 0) {
                next = dtt_add(next, frm.doc.frequentie);
            }
            frm.set_value('laatst_uitgevoerd', today);
            frm.set_value('volgende_keer', next);
            frm.save().then(() => frappe.show_alert({
                message: __('Uitgevoerd. Volgende keer: {0}', [frappe.datetime.str_to_user(next)]),
                indicator: 'green'
            }));
        }).addClass('btn-primary');
    },
    laatst_uitgevoerd(frm) {
        if (frm.doc.laatst_uitgevoerd && DTT_INTERVAL[frm.doc.frequentie] && !frm.doc.volgende_keer) {
            frm.set_value('volgende_keer', dtt_add(frm.doc.laatst_uitgevoerd, frm.doc.frequentie));
        }
    }
});

frappe.listview_settings['Zapp Terugkerende Taak'] = {
    add_fields: ['volgende_keer', 'actief', 'frequentie'],
    get_indicator(doc) {
        if (!doc.actief) return [__('Inactief'), 'gray', 'actief,=,0'];
        if (doc.frequentie === 'Doorlopend') return [__('Doorlopend'), 'blue', 'frequentie,=,Doorlopend'];
        if (!doc.volgende_keer) return [__('Geen datum'), 'gray', 'volgende_keer,is,not set'];
        const diff = frappe.datetime.get_diff(doc.volgende_keer, frappe.datetime.get_today());
        if (diff < 0) return [__('Achterstallig'), 'red', 'volgende_keer,<,' + frappe.datetime.get_today()];
        if (diff <= 7) return [__('Binnen 7 dagen'), 'orange'];
        return [__('Gepland'), 'green'];
    }
};

frappe.ui.form.on('Purchase Invoice', {
    refresh: function(frm) {
        // Verwijder oude floating preview als die bestaat
        $('.pdf-preview-panel').remove();

        // Voeg PDF preview sectie toe aan het formulier
        if (!frm.fields_dict.pdf_preview_html) {
            // Maak een custom HTML sectie voor de PDF
            let wrapper = frm.fields_dict.items.$wrapper.parent();

            // Voeg PDF frame toe boven de items tabel
            if (!$('#pdf-preview-frame').length) {
                let pdf_section = $(`
                    <div id="pdf-preview-frame" class="form-group" style="margin-bottom: 20px;">
                        <label class="control-label">Factuur PDF</label>
                        <div id="pdf-container" style="border: 1px solid #d1d8dd; border-radius: 4px; background: #f5f7fa; min-height: 600px;">
                            <p style="padding: 20px; color: #8d99a6;">Geen PDF bijlage gevonden</p>
                        </div>
                    </div>
                `);
                wrapper.before(pdf_section);
            }
        }

        // Zoek PDF bijlage
        frappe.call({
            method: 'frappe.client.get_list',
            args: {
                doctype: 'File',
                filters: {
                    attached_to_doctype: 'Purchase Invoice',
                    attached_to_name: frm.doc.name,
                    file_url: ['like', '%.pdf']
                },
                fields: ['file_url', 'file_name'],
                limit_page_length: 1
            },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    let file_url = r.message[0].file_url;
                    $('#pdf-container').html(`
                        <iframe src="${file_url}" 
                            style="width: 100%; height: 700px; border: none;"
                            title="PDF Preview">
                        </iframe>
                    `);
                } else {
                    $('#pdf-container').html('<p style="padding: 20px; color: #8d99a6;">Geen PDF bijlage gevonden</p>');
                }
            }
        });
    }
});

// Force sidebar always visible
(function() {
    if (window._sidebar_forced) return;
    window._sidebar_forced = true;

    function forceSidebar() {
        // Remove any collapsed state
        $('body').removeClass('sidebar-collapsed');
        $('.layout-side-section').show().css({
            'display': 'block',
            'visibility': 'visible',
            'width': '220px'
        });
        $('.desk-sidebar').show();

        // Hide collapse button
        $('.collapse-sidebar-btn, .sidebar-toggle-btn').hide();

        // Store preference
        if (typeof frappe !== 'undefined' && frappe.ui && frappe.ui.sidebar) {
            frappe.ui.sidebar.collapsed = false;
        }
    }

    // Apply immediately and on changes
    forceSidebar();
    $(document).ready(forceSidebar);

    // Observe DOM changes
    const observer = new MutationObserver(forceSidebar);
    observer.observe(document.body, {attributes: true, childList: true, subtree: true});

    // Also on route changes
    if (typeof frappe !== 'undefined' && frappe.router) {
        frappe.router.on('change', function() {
            setTimeout(forceSidebar, 100);
        });
    }
})();
